import pandas as pd
import json
import numpy as np

DATA_FILE = "/home/chs/Work/tga_plot/eval/inputs_b/rheology.csv"

# Read the CSV file
df = pd.read_csv(DATA_FILE)

# Clean column names
df.columns = [c.strip() for c in df.columns]

# Identify columns based on preview info
# Col A: Angular frequency (rad/s)
# Col B: Storage modulus G' (Pa)
# Col C: Loss modulus G'' (Pa)

freq_col = 'Angular frequency (rad/s)'
g_prime_col = "Storage modulus G' (Pa)"
g_double_prime_col = "Loss modulus G'' (Pa)"

# Extract data
x_data = df[freq_col].dropna().values
y1_data = df[g_prime_col].dropna().values
y2_data = df[g_double_prime_col].dropna().values

# Ensure arrays are same length after dropping NaNs if necessary, 
# but usually they align. Let's filter rows where all are valid.
mask = ~np.isnan(x_data) & ~np.isnan(y1_data) & ~np.isnan(y2_data)
x_clean = x_data[mask]
y1_clean = y1_data[mask]
y2_clean = y2_data[mask]

# Prepare series data for ECharts
series_g_prime = [[float(x), float(y)] for x, y in zip(x_clean, y1_clean)]
series_g_double_prime = [[float(x), float(y)] for x, y in zip(x_clean, y2_clean)]

# Define colors
color_g_prime = '#5470C6'
color_g_double_prime = '#91CC75'

